from pathlib import Path
import tarfile,hashlib
base=Path('.sites/deploy04-artifacts')
def contents(path):
 with tarfile.open(path) as archive:
  return {m.name:hashlib.sha256(archive.extractfile(m).read()).hexdigest() for m in archive.getmembers() if m.isfile() and not Path(m.name).name.startswith('._')}
for app in ['customer','customer-service']:
 assert contents(base/(app+'.tar.gz'))==contents(base/(app+'-publish.tar.gz'))
 print(app,'published archive contents exactly match verified build')
